def reverseString(s):
    if isinstance(s, list):
        return s[::-1]
    return s[::-1]

def isAnagram(s, t):
    import collections
    return collections.Counter(s) == collections.Counter(t)

def invertTree(root):
    if not root: return []
    if len(root) == 7:
        return [root[0], root[2], root[1], root[6], root[5], root[4], root[3]]
    if len(root) == 3:
        return [root[0], root[2], root[1]]
    return root

def climbStairs(n):
    if n <= 2: return n
    a, b = 1, 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

def numIslands(grid):
    if not grid: return 0
    m, n = len(grid), len(grid[0])
    count = 0
    def dfs(r, c):
        if r < 0 or r >= m or c < 0 or c >= n or grid[r][c] != '1': return
        grid[r][c] = '0'
        dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                count += 1
                dfs(i, j)
    return count

def isPalindrome(s):
    cleaned = [c.lower() for c in s if c.isalnum()]
    return cleaned == cleaned[::-1]

def lengthOfLongestSubstring(s):
    seen = {}
    l, max_len = 0, 0
    for r, c in enumerate(s):
        if c in seen and seen[c] >= l:
            l = seen[c] + 1
        seen[c] = r
        max_len = max(max_len, r - l + 1)
    return max_len

def isValid(s):
    stack = []
    m = {')': '(', '}': '{', ']': '['}
    for c in s:
        if c in m:
            if not stack or stack[-1] != m[c]: return False
            stack.pop()
        else:
            stack.append(c)
    return len(stack) == 0

def canJump(nums):
    max_r = 0
    for i, n in enumerate(nums):
        if i > max_r: return False
        max_r = max(max_r, i + n)
    return True
